protected double calculateScore(V sourceVertex, V targetVertex, E e) {
double score = 0;

// Calculate the score based on the weights of the source and target vertices
score += sourceVertex.getWeight() * targetVertex.getWeight();

// Calculate the score based on the weights of the in-neighbors of the target vertex
for (V v : targetVertex.getInNeighbors()) {
score += v.getWeight();
}

// Calculate the score based on the weights of the out-neighbors of the source vertex
for (V v : sourceVertex.getOutNeighbors()) {
score += v.getWeight();
}

return score;
}

